using LibraryManagementSystem.Server.Dtos.Genres;
using LibraryManagementSystem.Server.Models;
using Riok.Mapperly.Abstractions;

namespace LibraryManagementSystem.Server.Mapping
{
    [Mapper]
    public static partial class GenreMapper
    {
        [MapperRequiredMapping(RequiredMappingStrategy.Target)]
        public static partial GenreDto ToDto(Genre genre);

        // The key is generated by EF and the Books collection is managed through the books themselves.
        [MapperRequiredMapping(RequiredMappingStrategy.Source)]
        public static partial Genre ToEntity(GenreRequest request);

        [MapperRequiredMapping(RequiredMappingStrategy.Source)]
        public static partial void Apply(GenreRequest request, [MappingTarget] Genre genre);
    }
}
